    event.preventDefault();
    const form = event.currentTarget;
    const data = Object.fromEntries(new FormData(form));
    setBusy(true); setError('');
    try { await post('/api/card/pan', data); form.reset(); setMessage('Полный номер карты сохранён.'); await load(); }
    catch (e) { setError(userError(e)); form.querySelector('[name="pan"]').value = ''; }
